"""A non-executing interpreter for pickle's stack machine.

Values from artifacts are literals or the symbolic objects below. GLOBAL does
not import anything, and REDUCE/BUILD never dispatch to a Python object from
an artifact. The only real operations performed are explicitly selected,
side-effect-free operations on literal data and container parsers.
"""
from __future__ import annotations

import _compat_pickle
import base64
import binascii
import io
import math
import operator
import pickletools
import re
from dataclasses import dataclass, field

from modelgate.limits import Budget, ScanLimit
from modelgate.policy import CALL_CAPABILITIES, NESTED_LOADERS
from modelgate.report import Finding


@dataclass(eq=False)
class Unknown:
    description: str = "unknown value"


UNKNOWN = Unknown()
MARK = object()
TORCH_MAGIC = 0x1950A86A20F9469CFC6C


@dataclass(frozen=True)
class Ref:
    name: str


@dataclass(frozen=True)
class Module:
    name: str


@dataclass(eq=False)
class Instance:
    cls: object
    args: tuple = ()
    attrs: dict = field(default_factory=dict)
    state: object = None


@dataclass(eq=False)
class Partial:
    fn: object
    args: tuple = ()
    kwargs: dict = field(default_factory=dict)
    attrs: dict = field(default_factory=dict)


@dataclass(eq=False)
class Bound:
    obj: object
    name: str


@dataclass(eq=False)
class Helper:
    kind: str
    args: tuple
    kwargs: dict = field(default_factory=dict)


@dataclass(eq=False)
class Buffer:
    data: object = b""
    pos: int = 0


@dataclass(eq=False)
class Code:
    data: object


@dataclass(eq=False)
class Function:
    code: object
    attrs: dict = field(default_factory=dict)


@dataclass(eq=False)
class DynamicClass:
    name: str
    bases: tuple
    attrs: dict


@dataclass(eq=False)
class Lazy:
    kind: str
